-- Упражнения книги 19, глава 1 (Администрирование Linux). Файл строит автор-скрипт (не в репозитории); после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 1, 'la1-sshd-value', 0, 'func', 'Эффективное значение в sshd_config', 'Напишите функцию sshd_value(config, key, user, groups, addr): значение параметра key для входящего соединения пользователя user (строка) из групп groups (список строк) с адреса addr (строка). config — текст sshd_config. Правила. Пустые строки и строки, начинающиеся с # (после пробелов), пропускаются. Слово параметра и слово критерия читаются без учёта регистра, а аргументы — с учётом. Значение — остаток строки, пробелы между словами схлопываются в один. Для большинства параметров действует первое найденное значение, остальные игнорируются. Исключение — накапливаемые параметры allowusers, denyusers, allowgroups, denygroups, port и listenaddress: берутся значения всех подходящих строк, склеенные одним пробелом. Строки до первого Match относятся ко всем соединениям. Строка Match открывает блок, который длится до следующего Match; её аргументы — либо одно слово All (подходит всем), либо пары «критерий шаблоны» с критериями user, group и address; блок действует, если выполнены все критерии. Шаблоны — список через запятую; * и ? — подстановочные знаки; ! в начале шаблона означает отрицание: если совпал хоть один отрицательный шаблон, критерий не выполнен, иначе нужен хотя бы один совпавший положительный. user сравнивается с user, group — с любой из групп, address — с addr; шаблон address, содержащий /, считается сетью в записи CIDR (адрес входит в сеть), остальные — обычными подстановочными. Match с неизвестным критерием никогда не действует. Строки вне действующего блока пропускаются. Если параметра нет, верните пустую строку.', 'def sshd_value(config, key, user, groups, addr):
    pass
', 'Заведите флаг active (до первого Match он True), на каждой строке Match пересчитывайте его. Для обычного параметра вернитесь на первой подходящей строке, для накапливаемых собирайте список.', '{"func": "sshd_value", "tests": [{"args": ["# sshd_config of a small server\nPort 22\nPort 2222\nPermitRootLogin no\nPasswordAuthentication no\nAllowUsers deploy admin\nAllowUsers   ops@*\nSubsystem sftp /usr/lib/openssh/sftp-server\n\nMatch User backup,!guest\n    PasswordAuthentication yes\n    AllowUsers backup\n    ForceCommand /usr/local/bin/backup-only\nMatch Group sftp-*  Address 192.168.0.0/16,!192.168.5.*\n    ChrootDirectory /srv/sftp\n    ForceCommand internal-sftp\nMatch Address 10.*\n    PermitRootLogin prohibit-password\nMatch All\n    MaxAuthTries 3\n", "Port", "alice", [], "203.0.113.9"], "expected": "22 2222"}, {"args": ["# sshd_config of a small server\nPort 22\nPort 2222\nPermitRootLogin no\nPasswordAuthentication no\nAllowUsers deploy admin\nAllowUsers   ops@*\nSubsystem sftp /usr/lib/openssh/sftp-server\n\nMatch User backup,!guest\n    PasswordAuthentication yes\n    AllowUsers backup\n    ForceCommand /usr/local/bin/backup-only\nMatch Group sftp-*  Address 192.168.0.0/16,!192.168.5.*\n    ChrootDirectory /srv/sftp\n    ForceCommand internal-sftp\nMatch Address 10.*\n    PermitRootLogin prohibit-password\nMatch All\n    MaxAuthTries 3\n", "passwordauthentication", "backup", ["backup"], "10.1.1.1"], "expected": "no"}, {"args": ["# sshd_config of a small server\nPort 22\nPort 2222\nPermitRootLogin no\nPasswordAuthentication no\nAllowUsers deploy admin\nAllowUsers   ops@*\nSubsystem sftp /usr/lib/openssh/sftp-server\n\nMatch User backup,!guest\n    PasswordAuthentication yes\n    AllowUsers backup\n    ForceCommand /usr/local/bin/backup-only\nMatch Group sftp-*  Address 192.168.0.0/16,!192.168.5.*\n    ChrootDirectory /srv/sftp\n    ForceCommand internal-sftp\nMatch Address 10.*\n    PermitRootLogin prohibit-password\nMatch All\n    MaxAuthTries 3\n", "ForceCommand", "backup", [], "198.51.100.4"], "expected": "/usr/local/bin/backup-only"}, {"args": ["# sshd_config of a small server\nPort 22\nPort 2222\nPermitRootLogin no\nPasswordAuthentication no\nAllowUsers deploy admin\nAllowUsers   ops@*\nSubsystem sftp /usr/lib/openssh/sftp-server\n\nMatch User backup,!guest\n    PasswordAuthentication yes\n    AllowUsers backup\n    ForceCommand /usr/local/bin/backup-only\nMatch Group sftp-*  Address 192.168.0.0/16,!192.168.5.*\n    ChrootDirectory /srv/sftp\n    ForceCommand internal-sftp\nMatch Address 10.*\n    PermitRootLogin prohibit-password\nMatch All\n    MaxAuthTries 3\n", "ForceCommand", "guest", ["sftp-guests"], "192.168.5.7"], "expected": ""}, {"args": ["# sshd_config of a small server\nPort 22\nPort 2222\nPermitRootLogin no\nPasswordAuthentication no\nAllowUsers deploy admin\nAllowUsers   ops@*\nSubsystem sftp /usr/lib/openssh/sftp-server\n\nMatch User backup,!guest\n    PasswordAuthentication yes\n    AllowUsers backup\n    ForceCommand /usr/local/bin/backup-only\nMatch Group sftp-*  Address 192.168.0.0/16,!192.168.5.*\n    ChrootDirectory /srv/sftp\n    ForceCommand internal-sftp\nMatch Address 10.*\n    PermitRootLogin prohibit-password\nMatch All\n    MaxAuthTries 3\n", "ForceCommand", "alice", ["users", "sftp-staff"], "192.168.7.7"], "expected": "internal-sftp"}, {"args": ["# sshd_config of a small server\nPort 22\nPort 2222\nPermitRootLogin no\nPasswordAuthentication no\nAllowUsers deploy admin\nAllowUsers   ops@*\nSubsystem sftp /usr/lib/openssh/sftp-server\n\nMatch User backup,!guest\n    PasswordAuthentication yes\n    AllowUsers backup\n    ForceCommand /usr/local/bin/backup-only\nMatch Group sftp-*  Address 192.168.0.0/16,!192.168.5.*\n    ChrootDirectory /srv/sftp\n    ForceCommand internal-sftp\nMatch Address 10.*\n    PermitRootLogin prohibit-password\nMatch All\n    MaxAuthTries 3\n", "ChrootDirectory", "alice", ["sftp-staff"], "192.168.1.1"], "expected": "/srv/sftp"}, {"args": ["# sshd_config of a small server\nPort 22\nPort 2222\nPermitRootLogin no\nPasswordAuthentication no\nAllowUsers deploy admin\nAllowUsers   ops@*\nSubsystem sftp /usr/lib/openssh/sftp-server\n\nMatch User backup,!guest\n    PasswordAuthentication yes\n    AllowUsers backup\n    ForceCommand /usr/local/bin/backup-only\nMatch Group sftp-*  Address 192.168.0.0/16,!192.168.5.*\n    ChrootDirectory /srv/sftp\n    ForceCommand internal-sftp\nMatch Address 10.*\n    PermitRootLogin prohibit-password\nMatch All\n    MaxAuthTries 3\n", "ChrootDirectory", "alice", ["sftp-staff"], "172.16.0.1"], "expected": ""}, {"args": ["# sshd_config of a small server\nPort 22\nPort 2222\nPermitRootLogin no\nPasswordAuthentication no\nAllowUsers deploy admin\nAllowUsers   ops@*\nSubsystem sftp /usr/lib/openssh/sftp-server\n\nMatch User backup,!guest\n    PasswordAuthentication yes\n    AllowUsers backup\n    ForceCommand /usr/local/bin/backup-only\nMatch Group sftp-*  Address 192.168.0.0/16,!192.168.5.*\n    ChrootDirectory /srv/sftp\n    ForceCommand internal-sftp\nMatch Address 10.*\n    PermitRootLogin prohibit-password\nMatch All\n    MaxAuthTries 3\n", "PermitRootLogin", "root", [], "10.1.2.3"], "expected": "no"}, {"args": ["# sshd_config of a small server\nPort 22\nPort 2222\nPermitRootLogin no\nPasswordAuthentication no\nAllowUsers deploy admin\nAllowUsers   ops@*\nSubsystem sftp /usr/lib/openssh/sftp-server\n\nMatch User backup,!guest\n    PasswordAuthentication yes\n    AllowUsers backup\n    ForceCommand /usr/local/bin/backup-only\nMatch Group sftp-*  Address 192.168.0.0/16,!192.168.5.*\n    ChrootDirectory /srv/sftp\n    ForceCommand internal-sftp\nMatch Address 10.*\n    PermitRootLogin prohibit-password\nMatch All\n    MaxAuthTries 3\n", "AllowUsers", "backup", [], "1.2.3.4"], "expected": "deploy admin ops@* backup"}, {"args": ["# sshd_config of a small server\nPort 22\nPort 2222\nPermitRootLogin no\nPasswordAuthentication no\nAllowUsers deploy admin\nAllowUsers   ops@*\nSubsystem sftp /usr/lib/openssh/sftp-server\n\nMatch User backup,!guest\n    PasswordAuthentication yes\n    AllowUsers backup\n    ForceCommand /usr/local/bin/backup-only\nMatch Group sftp-*  Address 192.168.0.0/16,!192.168.5.*\n    ChrootDirectory /srv/sftp\n    ForceCommand internal-sftp\nMatch Address 10.*\n    PermitRootLogin prohibit-password\nMatch All\n    MaxAuthTries 3\n", "AllowUsers", "carol", [], "1.2.3.4"], "expected": "deploy admin ops@*"}, {"args": ["# sshd_config of a small server\nPort 22\nPort 2222\nPermitRootLogin no\nPasswordAuthentication no\nAllowUsers deploy admin\nAllowUsers   ops@*\nSubsystem sftp /usr/lib/openssh/sftp-server\n\nMatch User backup,!guest\n    PasswordAuthentication yes\n    AllowUsers backup\n    ForceCommand /usr/local/bin/backup-only\nMatch Group sftp-*  Address 192.168.0.0/16,!192.168.5.*\n    ChrootDirectory /srv/sftp\n    ForceCommand internal-sftp\nMatch Address 10.*\n    PermitRootLogin prohibit-password\nMatch All\n    MaxAuthTries 3\n", "MaxAuthTries", "carol", [], "1.2.3.4"], "expected": "3"}, {"args": ["# sshd_config of a small server\nPort 22\nPort 2222\nPermitRootLogin no\nPasswordAuthentication no\nAllowUsers deploy admin\nAllowUsers   ops@*\nSubsystem sftp /usr/lib/openssh/sftp-server\n\nMatch User backup,!guest\n    PasswordAuthentication yes\n    AllowUsers backup\n    ForceCommand /usr/local/bin/backup-only\nMatch Group sftp-*  Address 192.168.0.0/16,!192.168.5.*\n    ChrootDirectory /srv/sftp\n    ForceCommand internal-sftp\nMatch Address 10.*\n    PermitRootLogin prohibit-password\nMatch All\n    MaxAuthTries 3\n", "LoginGraceTime", "carol", [], "1.2.3.4"], "expected": ""}, {"args": ["Match User bob\n\tPasswordAuthentication yes\nMatch All\nPasswordAuthentication no\nmatch user Bob\n    X11Forwarding yes\n", "PasswordAuthentication", "bob", [], "::1"], "expected": "yes"}, {"args": ["Match User bob\n\tPasswordAuthentication yes\nMatch All\nPasswordAuthentication no\nmatch user Bob\n    X11Forwarding yes\n", "PasswordAuthentication", "carol", [], "::1"], "expected": "no"}, {"args": ["Match User bob\n\tPasswordAuthentication yes\nMatch All\nPasswordAuthentication no\nmatch user Bob\n    X11Forwarding yes\n", "X11Forwarding", "Bob", [], "::1"], "expected": "yes"}, {"args": ["Match User bob\n\tPasswordAuthentication yes\nMatch All\nPasswordAuthentication no\nmatch user Bob\n    X11Forwarding yes\n", "X11Forwarding", "bob", [], "::1"], "expected": ""}, {"args": ["", "Port", "u", [], "1.1.1.1"], "expected": ""}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 1, 'la1-ssh-config', 1, 'func', 'Клиентский ssh_config', 'Напишите функцию ssh_effective(config, host): итоговые параметры клиента ssh для команды «ssh host». Верните словарь, ключи — имена параметров в нижнем регистре, значения — строки. config — текст файла ~/.ssh/config. Строка параметра — слово и значение, разделённые пробелами или знаком = (вокруг = могут быть пробелы); значение — остаток строки, обрезанный по краям. Пустые строки и строки с # в начале пропускаются. Строки до первой строки Host относятся ко всем хостам. Строка Host содержит один или несколько шаблонов через пробел (* и ? — подстановочные знаки, регистр учитывается); блок действует до следующей строки Host и применяется, если host совпал хотя бы с одним положительным шаблоном и ни с одним шаблоном с ! в начале (шаблон с ! сам по себе ничего не включает). Шаблоны сравниваются с именем host так, как оно записано в команде; параметр hostname на сопоставление не влияет. Для каждого параметра берётся первое найденное значение. Исключение — identityfile: в результате это список строк, куда попадают все значения из всех подходящих блоков в порядке появления. Match в config не встречается.', 'def ssh_effective(config, host):
    pass
', 'Разберите строку регулярным выражением (\S+?)(?:\s*=\s*|\s+)(.*). Для Host: если совпал отрицательный шаблон, блок не действует; иначе нужен положительный.', '{"func": "ssh_effective", "tests": [{"args": ["# ~/.ssh/config\nCompression no\n\nHost bastion\n    HostName 203.0.113.10\n    User jump\n    IdentityFile ~/.ssh/jump_ed25519\n\nHost db-* !db-test\n    User dba\n    ProxyJump bastion\n    IdentityFile ~/.ssh/db_ed25519\n\nHost db-prod?\n    HostName=10.0.5.9\n    User  root\n    Port = 2222\n\nHost *\n    User ann\n    IdentitiesOnly yes\n    IdentityFile ~/.ssh/id_ed25519\n    ServerAliveInterval 30\n", "bastion"], "expected": {"compression": "no", "hostname": "203.0.113.10", "user": "jump", "identityfile": ["~/.ssh/jump_ed25519", "~/.ssh/id_ed25519"], "identitiesonly": "yes", "serveraliveinterval": "30"}}, {"args": ["# ~/.ssh/config\nCompression no\n\nHost bastion\n    HostName 203.0.113.10\n    User jump\n    IdentityFile ~/.ssh/jump_ed25519\n\nHost db-* !db-test\n    User dba\n    ProxyJump bastion\n    IdentityFile ~/.ssh/db_ed25519\n\nHost db-prod?\n    HostName=10.0.5.9\n    User  root\n    Port = 2222\n\nHost *\n    User ann\n    IdentitiesOnly yes\n    IdentityFile ~/.ssh/id_ed25519\n    ServerAliveInterval 30\n", "db-prod1"], "expected": {"compression": "no", "user": "dba", "proxyjump": "bastion", "identityfile": ["~/.ssh/db_ed25519", "~/.ssh/id_ed25519"], "hostname": "10.0.5.9", "port": "2222", "identitiesonly": "yes", "serveraliveinterval": "30"}}, {"args": ["# ~/.ssh/config\nCompression no\n\nHost bastion\n    HostName 203.0.113.10\n    User jump\n    IdentityFile ~/.ssh/jump_ed25519\n\nHost db-* !db-test\n    User dba\n    ProxyJump bastion\n    IdentityFile ~/.ssh/db_ed25519\n\nHost db-prod?\n    HostName=10.0.5.9\n    User  root\n    Port = 2222\n\nHost *\n    User ann\n    IdentitiesOnly yes\n    IdentityFile ~/.ssh/id_ed25519\n    ServerAliveInterval 30\n", "db-test"], "expected": {"compression": "no", "user": "ann", "identitiesonly": "yes", "identityfile": ["~/.ssh/id_ed25519"], "serveraliveinterval": "30"}}, {"args": ["# ~/.ssh/config\nCompression no\n\nHost bastion\n    HostName 203.0.113.10\n    User jump\n    IdentityFile ~/.ssh/jump_ed25519\n\nHost db-* !db-test\n    User dba\n    ProxyJump bastion\n    IdentityFile ~/.ssh/db_ed25519\n\nHost db-prod?\n    HostName=10.0.5.9\n    User  root\n    Port = 2222\n\nHost *\n    User ann\n    IdentitiesOnly yes\n    IdentityFile ~/.ssh/id_ed25519\n    ServerAliveInterval 30\n", "db-prod12"], "expected": {"compression": "no", "user": "dba", "proxyjump": "bastion", "identityfile": ["~/.ssh/db_ed25519", "~/.ssh/id_ed25519"], "identitiesonly": "yes", "serveraliveinterval": "30"}}, {"args": ["# ~/.ssh/config\nCompression no\n\nHost bastion\n    HostName 203.0.113.10\n    User jump\n    IdentityFile ~/.ssh/jump_ed25519\n\nHost db-* !db-test\n    User dba\n    ProxyJump bastion\n    IdentityFile ~/.ssh/db_ed25519\n\nHost db-prod?\n    HostName=10.0.5.9\n    User  root\n    Port = 2222\n\nHost *\n    User ann\n    IdentitiesOnly yes\n    IdentityFile ~/.ssh/id_ed25519\n    ServerAliveInterval 30\n", "web"], "expected": {"compression": "no", "user": "ann", "identitiesonly": "yes", "identityfile": ["~/.ssh/id_ed25519"], "serveraliveinterval": "30"}}, {"args": ["# ~/.ssh/config\nCompression no\n\nHost bastion\n    HostName 203.0.113.10\n    User jump\n    IdentityFile ~/.ssh/jump_ed25519\n\nHost db-* !db-test\n    User dba\n    ProxyJump bastion\n    IdentityFile ~/.ssh/db_ed25519\n\nHost db-prod?\n    HostName=10.0.5.9\n    User  root\n    Port = 2222\n\nHost *\n    User ann\n    IdentitiesOnly yes\n    IdentityFile ~/.ssh/id_ed25519\n    ServerAliveInterval 30\n", "Bastion"], "expected": {"compression": "no", "user": "ann", "identitiesonly": "yes", "identityfile": ["~/.ssh/id_ed25519"], "serveraliveinterval": "30"}}, {"args": ["", "x"], "expected": {}}, {"args": ["Host a b\n  User one\nHost !a *\n  User two\n  Port=22\n", "a"], "expected": {"user": "one"}}, {"args": ["Host a b\n  User one\nHost !a *\n  User two\n  Port=22\n", "c"], "expected": {"user": "two", "port": "22"}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 1, 'la1-authkeys-parse', 2, 'func', 'Разбор authorized_keys', 'Напишите функцию parse_authorized_keys(text): разберите файл authorized_keys и верните список кортежей (options, keytype, comment) в порядке строк. Строка: необязательные options, тип ключа, ключ в base64, необязательный комментарий (всё остальное до конца строки, обрезанное по краям, иначе пустая строка). Пустые строки и строки с # в начале (после пробелов) пропускаются. Известные типы: ssh-ed25519, ssh-rsa, ecdsa-sha2-nistp256, ecdsa-sha2-nistp384, ecdsa-sha2-nistp521, sk-ssh-ed25519@openssh.com, sk-ecdsa-sha2-nistp256@openssh.com. Если первое слово строки — тип ключа, options нет. Иначе первое слово — options: оно может содержать пробелы только внутри двойных кавычек, а внутри кавычек \" — это символ кавычки. Строки, где после options нет известного типа и ключа (хотя бы одного слова после типа), пропускаются. Options — это список через запятую (запятая внутри кавычек не разделяет); элемент имя или имя=значение. Результат options — словарь: имя в нижнем регистре; для имени без значения True; для имени=значение — строка значения, где обрамляющие кавычки сняты, а \" заменено на ". Если имя повторяется, остаётся первое вхождение. Без options верните пустой словарь.', 'def parse_authorized_keys(text):
    pass
', 'Сначала найдите конец первого слова, учитывая кавычки и обратную косую; потом отдельной функцией разрежьте options по запятым вне кавычек.', '{"func": "parse_authorized_keys", "tests": [{"args": ["# deploy keys\nssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIJ80k8WIHNVmYeoZm+4cPX6dBU7CWNUX+B2brTFyAeUx ann@laptop\n\nfrom=\"10.0.0.0/8,192.0.2.7\",no-port-forwarding,no-pty ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIAAJ5RTvZuuKGUlWypNxHEHSP8hj5+1cYtISk0hIBYzi backup job\ncommand=\"/usr/local/bin/backup --dest \\\"/srv/b ackup\\\"\",restrict ssh-rsa AAAAB3NzaC1yc2EAAAADAQABAAABgQC7 ci runner\n   \nthis line has no key at all\nenvironment=\"A=1,B=2\",expiry-time=\"20271231\" ecdsa-sha2-nistp256 AAAAE2VjZHNhLXNoYTItbmlzdHAyNTYAAAAIbmlzdHAyNTYAAABBBEEzf0CTrGY3+36J91GPPYwXd8BfD3Df7IspbKFMExzP1gAF1yQePYh4/kP/sY+c/7Ys/NRf9z+lPCYoRCRov04=\n\tCOMMAND=\"id\",command=\"whoami\" sk-ssh-ed25519@openssh.com AAAAC3NzaC1lZDI1NTE5AAAAIAIiDILfEOpeidhx4Lw3a1HHQj+N60cE74oBFKSaXYQj\nno-pty ssh-ed25519\n"], "expected": [{"__tuple__": [{}, "ssh-ed25519", "ann@laptop"]}, {"__tuple__": [{"from": "10.0.0.0/8,192.0.2.7", "no-port-forwarding": true, "no-pty": true}, "ssh-ed25519", "backup job"]}, {"__tuple__": [{"command": "/usr/local/bin/backup --dest \"/srv/b ackup\"", "restrict": true}, "ssh-rsa", "ci runner"]}, {"__tuple__": [{"environment": "A=1,B=2", "expiry-time": "20271231"}, "ecdsa-sha2-nistp256", ""]}, {"__tuple__": [{"command": "id"}, "sk-ssh-ed25519@openssh.com", ""]}]}, {"args": [""], "expected": []}, {"args": ["# only a comment\n\n"], "expected": []}, {"args": ["ssh-rsa AAAAB3Nza\nssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIJ80k8WIHNVmYeoZm+4cPX6dBU7CWNUX+B2brTFyAeUx\n"], "expected": [{"__tuple__": [{}, "ssh-rsa", ""]}, {"__tuple__": [{}, "ssh-ed25519", ""]}]}, {"args": ["restrict,command=\"echo a,b\" ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIJ80k8WIHNVmYeoZm+4cPX6dBU7CWNUX+B2brTFyAeUx x y z\n"], "expected": [{"__tuple__": [{"restrict": true, "command": "echo a,b"}, "ssh-ed25519", "x y z"]}]}, {"args": ["from=\"*.example.org,!bad.example.org\" ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIAAJ5RTvZuuKGUlWypNxHEHSP8hj5+1cYtISk0hIBYzi  \n"], "expected": [{"__tuple__": [{"from": "*.example.org,!bad.example.org"}, "ssh-ed25519", ""]}]}, {"args": ["command=\"x\",COMMAND=\"y\",Restrict ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIAIiDILfEOpeidhx4Lw3a1HHQj+N60cE74oBFKSaXYQj c\n"], "expected": [{"__tuple__": [{"command": "x", "restrict": true}, "ssh-ed25519", "c"]}]}, {"args": ["command=\"unterminated ssh-ed25519 AAAA c\n"], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 1, 'la1-key-access', 3, 'func', 'Что разрешает строка authorized_keys', 'Напишите функцию key_access(opts, addr, now, request): решение для входа по ключу. opts — словарь options одной строки authorized_keys (как из разбора: имена в нижнем регистре, True для флагов, строки для значений), addr — адрес клиента, now — текущее время строкой YYYYMMDDHHMMSS (UTC), request — одно из: "shell", "exec:<команда>", "pty", "port-forward", "agent-forward", "x11-forward". Проверки идут по порядку. 1) Если есть from: это список шаблонов через запятую; шаблон с ! в начале — отрицание; шаблон с / — сеть CIDR, иначе * и ? — подстановочные знаки по тексту адреса. Адрес допускается, если совпал хотя бы один положительный шаблон и ни один отрицательный; иначе верните "denied:from". 2) Если есть expiry-time (YYYYMMDD или YYYYMMDDHHMM или YYYYMMDDHHMMSS, возможно с Z на конце, которое игнорируется): значение дополняется нулями справа до 14 цифр; если now не меньше него, верните "denied:expired". 3) Для "shell" и "exec:...": если есть command, верните "run:" и значение command (команда клиента подменяется), иначе "ok". 4) Для остальных запросов возможность называется: pty, port-forwarding, agent-forwarding, x11-forwarding соответственно. Возможность выключена, если есть флаг no-<имя>; иначе включена, если есть флаг <имя>; иначе выключена, если есть restrict; иначе включена. Выключенную верните как "denied:" и имя возможности, включённую — "ok".', 'def key_access(opts, addr, now, request):
    pass
', 'Сравнивать now и срок можно как строки одинаковой длины. Для возможностей напишите маленькую функцию cap(name) с тремя проверками по порядку.', '{"func": "key_access", "tests": [{"args": [{}, "203.0.113.5", "20261103120000", "shell"], "expected": "ok"}, {"args": [{"from": "10.0.0.0/8,192.0.2.7"}, "10.20.30.40", "20261103120000", "pty"], "expected": "ok"}, {"args": [{"from": "10.0.0.0/8,192.0.2.7"}, "192.0.2.8", "20261103120000", "shell"], "expected": "denied:from"}, {"args": [{"from": "10.*,!10.9.*"}, "10.9.1.1", "20261103120000", "shell"], "expected": "denied:from"}, {"args": [{"from": "10.*,!10.9.*"}, "10.8.1.1", "20261103120000", "shell"], "expected": "ok"}, {"args": [{"from": "!10.9.*"}, "10.8.1.1", "20261103120000", "shell"], "expected": "denied:from"}, {"args": [{"expiry-time": "20261103"}, "1.1.1.1", "20261102235959", "shell"], "expected": "ok"}, {"args": [{"expiry-time": "20261103"}, "1.1.1.1", "20261103000001", "shell"], "expected": "denied:expired"}, {"args": [{"expiry-time": "202611031530Z"}, "1.1.1.1", "20261103152959", "shell"], "expected": "ok"}, {"args": [{"expiry-time": "202611031530Z"}, "1.1.1.1", "20261103153000", "shell"], "expected": "denied:expired"}, {"args": [{"command": "/usr/local/bin/backup", "restrict": true}, "1.1.1.1", "20261103120000", "exec:rm -rf /"], "expected": "run:/usr/local/bin/backup"}, {"args": [{"command": "/usr/local/bin/backup", "restrict": true}, "1.1.1.1", "20261103120000", "shell"], "expected": "run:/usr/local/bin/backup"}, {"args": [{"restrict": true}, "1.1.1.1", "20261103120000", "pty"], "expected": "denied:pty"}, {"args": [{"restrict": true, "pty": true}, "1.1.1.1", "20261103120000", "pty"], "expected": "ok"}, {"args": [{"restrict": true, "pty": true}, "1.1.1.1", "20261103120000", "port-forward"], "expected": "denied:port-forwarding"}, {"args": [{"no-pty": true, "pty": true}, "1.1.1.1", "20261103120000", "pty"], "expected": "denied:pty"}, {"args": [{"no-port-forwarding": true}, "1.1.1.1", "20261103120000", "port-forward"], "expected": "denied:port-forwarding"}, {"args": [{"no-port-forwarding": true}, "1.1.1.1", "20261103120000", "agent-forward"], "expected": "ok"}, {"args": [{"restrict": true, "x11-forwarding": true}, "1.1.1.1", "20261103120000", "x11-forward"], "expected": "ok"}, {"args": [{"from": "2001:db8::/32"}, "2001:db8::1", "20261103120000", "agent-forward"], "expected": "ok"}, {"args": [{"from": "10.0.0.0/8", "expiry-time": "20200101"}, "10.0.0.1", "20261103120000", "shell"], "expected": "denied:expired"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 1, 'la1-known-hosts', 4, 'func', 'Проверка хост-ключа по known_hosts', 'Напишите функцию known_hosts_check(text, host, port, key_type, key_blob): ответ клиента ssh на предъявленный хост-ключ. text — содержимое known_hosts, host — имя, port — номер порта (int), key_type и key_blob — тип ключа и его base64. Имя для поиска — host при порте 22 и «[host]:port» при другом порте, в нижнем регистре. Строка файла: необязательный маркер (@cert-authority или @revoked), поле хостов, тип ключа, base64 (остаток — комментарий). Пустые строки, строки с # в начале и строки короче трёх полей пропускаются; строки с @cert-authority и с любым другим маркером игнорируются. Поле хостов подходит так: если оно начинается с |, это хешированное имя «|1|соль|хеш» (соль и хеш в base64): берётся HMAC-SHA1 от искомого имени с ключом — декодированной солью и результат в base64 сравнивается с хешем; иначе это список шаблонов через запятую (* и ? — подстановочные знаки, регистр не учитывается), где ! в начале шаблона — отрицание: совпал отрицательный — строка не подходит, иначе нужен хотя бы один совпавший положительный. Ключ совпадает с предъявленным, если равны и тип, и base64. Ответ — строка: "revoked", если есть подходящая по хосту строка @revoked с предъявленным ключом (независимо от порядка строк); иначе "ok", если есть подходящая обычная строка с этим ключом; иначе "changed", если есть хоть одна подходящая по хосту обычная строка с другим ключом (даже другого типа); иначе "unknown".', 'def known_hosts_check(text, host, port, key_type, key_blob):
    pass
', 'Сначала решите, подходит ли строка по хосту, потом сравнивайте ключ. Хеш считается так: base64(hmac.new(b64decode(соль), имя.encode(), sha1).digest()).', '{"func": "known_hosts_check", "tests": [{"args": ["# known_hosts\ngit.example.org ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIAIiDILfEOpeidhx4Lw3a1HHQj+N60cE74oBFKSaXYQj\n*.lab.example.org,!old.lab.example.org ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIJ80k8WIHNVmYeoZm+4cPX6dBU7CWNUX+B2brTFyAeUx\n[files.example.org]:2200 ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIAAJ5RTvZuuKGUlWypNxHEHSP8hj5+1cYtISk0hIBYzi\n|1|5uDMQt4IE6lElIWedNI7JRzzcpc=|ijWPpWMcvaAXkLvwB0917mwiB6s= ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIJ80k8WIHNVmYeoZm+4cPX6dBU7CWNUX+B2brTFyAeUx\n|1|BOq58km8O8StXaCm/sxX68sThvE=|m/BJ/ZWM7zXiZagwGE5GSUItEpA= ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIAAJ5RTvZuuKGUlWypNxHEHSP8hj5+1cYtISk0hIBYzi\n@cert-authority *.corp.example.org ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIAIiDILfEOpeidhx4Lw3a1HHQj+N60cE74oBFKSaXYQj\nhost-a.example.org,203.0.113.7 ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIJ80k8WIHNVmYeoZm+4cPX6dBU7CWNUX+B2brTFyAeUx\nhost-a.example.org,203.0.113.7 ecdsa-sha2-nistp256 AAAAE2VjZHNhLXNoYTItbmlzdHAyNTYAAAAIbmlzdHAyNTYAAABBBEEzf0CTrGY3+36J91GPPYwXd8BfD3Df7IspbKFMExzP1gAF1yQePYh4/kP/sY+c/7Ys/NRf9z+lPCYoRCRov04=\n", "git.example.org", 22, "ssh-ed25519", "AAAAC3NzaC1lZDI1NTE5AAAAIAIiDILfEOpeidhx4Lw3a1HHQj+N60cE74oBFKSaXYQj"], "expected": "ok"}, {"args": ["# known_hosts\ngit.example.org ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIAIiDILfEOpeidhx4Lw3a1HHQj+N60cE74oBFKSaXYQj\n*.lab.example.org,!old.lab.example.org ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIJ80k8WIHNVmYeoZm+4cPX6dBU7CWNUX+B2brTFyAeUx\n[files.example.org]:2200 ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIAAJ5RTvZuuKGUlWypNxHEHSP8hj5+1cYtISk0hIBYzi\n|1|5uDMQt4IE6lElIWedNI7JRzzcpc=|ijWPpWMcvaAXkLvwB0917mwiB6s= ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIJ80k8WIHNVmYeoZm+4cPX6dBU7CWNUX+B2brTFyAeUx\n|1|BOq58km8O8StXaCm/sxX68sThvE=|m/BJ/ZWM7zXiZagwGE5GSUItEpA= ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIAAJ5RTvZuuKGUl