DI1NTE5AAAAIAAJ5RTvZuuKGUlWypNxHEHSP8hj5+1cYtISk0hIBYzi\n@revoked other.net ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIJ80k8WIHNVmYeoZm+4cPX6dBU7CWNUX+B2brTFyAeUx\nother.net ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIJ80k8WIHNVmYeoZm+4cPX6dBU7CWNUX+B2brTFyAeUx\n", "other.net", 22, "ssh-ed25519", "AAAAC3NzaC1lZDI1NTE5AAAAIJ80k8WIHNVmYeoZm+4cPX6dBU7CWNUX+B2brTFyAeUx"], "expected": "revoked"}, {"args": ["z.example.org ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIJ80k8WIHNVmYeoZm+4cPX6dBU7CWNUX+B2brTFyAeUx\n@revoked z.example.org ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIJ80k8WIHNVmYeoZm+4cPX6dBU7CWNUX+B2brTFyAeUx\n", "z.example.org", 22, "ssh-ed25519", "AAAAC3NzaC1lZDI1NTE5AAAAIJ80k8WIHNVmYeoZm+4cPX6dBU7CWNUX+B2brTFyAeUx"], "expected": "revoked"}, {"args": ["z.example.org ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIJ80k8WIHNVmYeoZm+4cPX6dBU7CWNUX+B2brTFyAeUx\n@revoked z.example.org ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIJ80k8WIHNVmYeoZm+4cPX6dBU7CWNUX+B2brTFyAeUx\n", "z.example.org", 22, "ssh-ed25519", "AAAAC3NzaC1lZDI1NTE5AAAAIAAJ5RTvZuuKGUlWypNxHEHSP8hj5+1cYtISk0hIBYzi"], "expected": "changed"}, {"args": ["", "h", 22, "ssh-ed25519", "AAAAC3NzaC1lZDI1NTE5AAAAIJ80k8WIHNVmYeoZm+4cPX6dBU7CWNUX+B2brTFyAeUx"], "expected": "unknown"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 1, 'la1-sudo-decision', 5, 'func', 'Решение sudo по sudoers', 'Напишите функцию sudo_decision(sudoers, user, groups, command): что скажет sudo пользователю user (в группах groups), который просит выполнить command (строка вида "/usr/bin/systemctl restart nginx"). Верните "deny", "password" или "nopasswd". Упрощённая модель sudoers. Строка, оканчивающаяся на \, склеивается со следующей (вместо \ ставится пробел). Пустые строки, строки с # в начале, Defaults и @include/@includedir пропускаются. User_Alias имя = список и Cmnd_Alias имя = список определяют псевдонимы; список — элементы через запятую; псевдонимы определены выше мест использования и не вложены друг в друга, кроме того, что в User_Alias могут быть имена, %группы и ALL. Остальные строки — правила: «пользователи ALL = [(кто)] команды». Пользователи — список через запятую: ALL, имя, %группа или псевдоним (отрицаний нет); слово ALL перед = — поле хоста, оно игнорируется. Необязательная часть (кто) сразу после = игнорируется. Команды — список через запятую, перед элементом могут стоять теги NOPASSWD: или PASSWD: (тег действует на этот и все следующие элементы правила, пока не встретится другой; в начале каждого правила действует PASSWD). Элемент — ALL, путь команды, путь с аргументами или имя Cmnd_Alias; перед элементом может стоять ! (отрицание, действует на весь псевдоним). Путь без аргументов подходит под любые аргументы, путь с аргументами — только под точно такую команду (пробелы нормализуются), ALL — под любую. Правила и элементы просматриваются по порядку, и действует последний подошедший элемент: отрицательный даёт "deny", обычный — "nopasswd" при действующем NOPASSWD и "password" иначе. Если ничего не подошло, "deny".', 'def sudo_decision(sudoers, user, groups, command):
    pass
', 'Склейте строки, соберите словари псевдонимов, затем идите по правилам: если пользователь подходит, перебирайте элементы и запоминайте результат последнего подошедшего.', '{"func": "sudo_decision", "tests": [{"args": ["Defaults env_reset\n# the users\nroot ALL=(ALL:ALL) ALL\nUser_Alias OPS = ann, %ops\nCmnd_Alias WEB = /usr/bin/systemctl restart nginx, /usr/bin/systemctl reload nginx\nCmnd_Alias SHELLS = /bin/sh, /bin/bash, /usr/bin/su\n%sudo ALL=(ALL:ALL) ALL\nOPS ALL=(root) NOPASSWD: WEB, PASSWD: /usr/bin/journalctl\ndeploy ALL = NOPASSWD: ALL, !SHELLS\n@includedir /etc/sudoers.d\n", "ann", [], "/usr/bin/systemctl restart nginx"], "expected": "nopasswd"}, {"args": ["Defaults env_reset\n# the users\nroot ALL=(ALL:ALL) ALL\nUser_Alias OPS = ann, %ops\nCmnd_Alias WEB = /usr/bin/systemctl restart nginx, /usr/bin/systemctl reload nginx\nCmnd_Alias SHELLS = /bin/sh, /bin/bash, /usr/bin/su\n%sudo ALL=(ALL:ALL) ALL\nOPS ALL=(root) NOPASSWD: WEB, PASSWD: /usr/bin/journalctl\ndeploy ALL = NOPASSWD: ALL, !SHELLS\n@includedir /etc/sudoers.d\n", "ann", [], "/usr/bin/systemctl stop nginx"], "expected": "deny"}, {"args": ["Defaults env_reset\n# the users\nroot ALL=(ALL:ALL) ALL\nUser_Alias OPS = ann, %ops\nCmnd_Alias WEB = /usr/bin/systemctl restart nginx, /usr/bin/systemctl reload nginx\nCmnd_Alias SHELLS = /bin/sh, /bin/bash, /usr/bin/su\n%sudo ALL=(ALL:ALL) ALL\nOPS ALL=(root) NOPASSWD: WEB, PASSWD: /usr/bin/journalctl\ndeploy ALL = NOPASSWD: ALL, !SHELLS\n@includedir /etc/sudoers.d\n", "ann", [], "/usr/bin/journalctl -u nginx"], "expected": "password"}, {"args": ["Defaults env_reset\n# the users\nroot ALL=(ALL:ALL) ALL\nUser_Alias OPS = ann, %ops\nCmnd_Alias WEB = /usr/bin/systemctl restart nginx, /usr/bin/systemctl reload nginx\nCmnd_Alias SHELLS = /bin/sh, /bin/bash, /usr/bin/su\n%sudo ALL=(ALL:ALL) ALL\nOPS ALL=(root) NOPASSWD: WEB, PASSWD: /usr/bin/journalctl\ndeploy ALL = NOPASSWD: ALL, !SHELLS\n@includedir /etc/sudoers.d\n", "bob", ["ops"], "/usr/bin/systemctl reload nginx"], "expected": "nopasswd"}, {"args": ["Defaults env_reset\n# the users\nroot ALL=(ALL:ALL) ALL\nUser_Alias OPS = ann, %ops\nCmnd_Alias WEB = /usr/bin/systemctl restart nginx, /usr/bin/systemctl reload nginx\nCmnd_Alias SHELLS = /bin/sh, /bin/bash, /usr/bin/su\n%sudo ALL=(ALL:ALL) ALL\nOPS ALL=(root) NOPASSWD: WEB, PASSWD: /usr/bin/journalctl\ndeploy ALL = NOPASSWD: ALL, !SHELLS\n@includedir /etc/sudoers.d\n", "bob", ["sudo"], "/usr/bin/systemctl stop nginx"], "expected": "password"}, {"args": ["Defaults env_reset\n# the users\nroot ALL=(ALL:ALL) ALL\nUser_Alias OPS = ann, %ops\nCmnd_Alias WEB = /usr/bin/systemctl restart nginx, /usr/bin/systemctl reload nginx\nCmnd_Alias SHELLS = /bin/sh, /bin/bash, /usr/bin/su\n%sudo ALL=(ALL:ALL) ALL\nOPS ALL=(root) NOPASSWD: WEB, PASSWD: /usr/bin/journalctl\ndeploy ALL = NOPASSWD: ALL, !SHELLS\n@includedir /etc/sudoers.d\n", "bob", ["sudo", "ops"], "/usr/bin/systemctl reload nginx"], "expected": "nopasswd"}, {"args": ["Defaults env_reset\n# the users\nroot ALL=(ALL:ALL) ALL\nUser_Alias OPS = ann, %ops\nCmnd_Alias WEB = /usr/bin/systemctl restart nginx, /usr/bin/systemctl reload nginx\nCmnd_Alias SHELLS = /bin/sh, /bin/bash, /usr/bin/su\n%sudo ALL=(ALL:ALL) ALL\nOPS ALL=(root) NOPASSWD: WEB, PASSWD: /usr/bin/journalctl\ndeploy ALL = NOPASSWD: ALL, !SHELLS\n@includedir /etc/sudoers.d\n", "deploy", [], "/usr/bin/apt update"], "expected": "nopasswd"}, {"args": ["Defaults env_reset\n# the users\nroot ALL=(ALL:ALL) ALL\nUser_Alias OPS = ann, %ops\nCmnd_Alias WEB = /usr/bin/systemctl restart nginx, /usr/bin/systemctl reload nginx\nCmnd_Alias SHELLS = /bin/sh, /bin/bash, /usr/bin/su\n%sudo ALL=(ALL:ALL) ALL\nOPS ALL=(root) NOPASSWD: WEB, PASSWD: /usr/bin/journalctl\ndeploy ALL = NOPASSWD: ALL, !SHELLS\n@includedir /etc/sudoers.d\n", "deploy", [], "/bin/bash"], "expected": "deny"}, {"args": ["Defaults env_reset\n# the users\nroot ALL=(ALL:ALL) ALL\nUser_Alias OPS = ann, %ops\nCmnd_Alias WEB = /usr/bin/systemctl restart nginx, /usr/bin/systemctl reload nginx\nCmnd_Alias SHELLS = /bin/sh, /bin/bash, /usr/bin/su\n%sudo ALL=(ALL:ALL) ALL\nOPS ALL=(root) NOPASSWD: WEB, PASSWD: /usr/bin/journalctl\ndeploy ALL = NOPASSWD: ALL, !SHELLS\n@includedir /etc/sudoers.d\n", "deploy", ["sudo"], "/bin/bash"], "expected": "deny"}, {"args": ["Defaults env_reset\n# the users\nroot ALL=(ALL:ALL) ALL\nUser_Alias OPS = ann, %ops\nCmnd_Alias WEB = /usr/bin/systemctl restart nginx, /usr/bin/systemctl reload nginx\nCmnd_Alias SHELLS = /bin/sh, /bin/bash, /usr/bin/su\n%sudo ALL=(ALL:ALL) ALL\nOPS ALL=(root) NOPASSWD: WEB, PASSWD: /usr/bin/journalctl\ndeploy ALL = NOPASSWD: ALL, !SHELLS\n@includedir /etc/sudoers.d\n", "deploy", ["sudo"], "/usr/bin/apt update"], "expected": "nopasswd"}, {"args": ["Defaults env_reset\n# the users\nroot ALL=(ALL:ALL) ALL\nUser_Alias OPS = ann, %ops\nCmnd_Alias WEB = /usr/bin/systemctl restart nginx, /usr/bin/systemctl reload nginx\nCmnd_Alias SHELLS = /bin/sh, /bin/bash, /usr/bin/su\n%sudo ALL=(ALL:ALL) ALL\nOPS ALL=(root) NOPASSWD: WEB, PASSWD: /usr/bin/journalctl\ndeploy ALL = NOPASSWD: ALL, !SHELLS\n@includedir /etc/sudoers.d\n", "root", [], "/bin/bash"], "expected": "password"}, {"args": ["Defaults env_reset\n# the users\nroot ALL=(ALL:ALL) ALL\nUser_Alias OPS = ann, %ops\nCmnd_Alias WEB = /usr/bin/systemctl restart nginx, /usr/bin/systemctl reload nginx\nCmnd_Alias SHELLS = /bin/sh, /bin/bash, /usr/bin/su\n%sudo ALL=(ALL:ALL) ALL\nOPS ALL=(root) NOPASSWD: WEB, PASSWD: /usr/bin/journalctl\ndeploy ALL = NOPASSWD: ALL, !SHELLS\n@includedir /etc/sudoers.d\n", "mallory", [], "/bin/ls"], "expected": "deny"}, {"args": ["ann ALL=(ALL) NOPASSWD: ALL\n%sudo ALL=(ALL:ALL) ALL\n", "ann", ["sudo"], "/usr/bin/apt update"], "expected": "password"}, {"args": ["ann ALL=(ALL) NOPASSWD: ALL\n%sudo ALL=(ALL:ALL) ALL\n", "ann", [], "/usr/bin/apt update"], "expected": "nopasswd"}, {"args": ["User_Alias ADMINS = ann, bob, \\\n    %wheel\nADMINS ALL=(ALL) /usr/bin/apt update, \\\n    /usr/bin/apt upgrade\ncarol ALL=(ALL) NOPASSWD: /usr/bin/ls\n", "bob", [], "/usr/bin/apt upgrade"], "expected": "password"}, {"args": ["User_Alias ADMINS = ann, bob, \\\n    %wheel\nADMINS ALL=(ALL) /usr/bin/apt update, \\\n    /usr/bin/apt upgrade\ncarol ALL=(ALL) NOPASSWD: /usr/bin/ls\n", "bob", [], "/usr/bin/apt upgrade -y"], "expected": "deny"}, {"args": ["User_Alias ADMINS = ann, bob, \\\n    %wheel\nADMINS ALL=(ALL) /usr/bin/apt update, \\\n    /usr/bin/apt upgrade\ncarol ALL=(ALL) NOPASSWD: /usr/bin/ls\n", "eve", ["wheel"], "/usr/bin/apt update"], "expected": "password"}, {"args": ["User_Alias ADMINS = ann, bob, \\\n    %wheel\nADMINS ALL=(ALL) /usr/bin/apt update, \\\n    /usr/bin/apt upgrade\ncarol ALL=(ALL) NOPASSWD: /usr/bin/ls\n", "carol", [], "/usr/bin/ls -la /root"], "expected": "nopasswd"}, {"args": ["", "ann", [], "/bin/true"], "expected": "deny"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 1, 'la1-key-fingerprint', 6, 'func', 'Отпечаток открытого ключа', 'Напишите функцию key_fingerprint(pubkey_line, algo): отпечаток так, как его печатает «ssh-keygen -l». pubkey_line — строка открытого ключа «тип base64 [комментарий]»; algo — "sha256" или "md5". Декодируйте base64 в байты blob. Внутри blob первым идёт поле: 4 байта длины (big-endian) и строка такой длины — это тип ключа, он должен совпадать с типом в pubkey_line. Для sha256 верните «SHA256:» и base64 от SHA-256 по всему blob без символов = в конце. Для md5 верните «MD5:» и 16 байт MD5 по blob в виде 32 шестнадцатеричных цифр в нижнем регистре, разбитых на пары через двоеточие. Если в строке меньше двух слов, base64 некорректен, blob короче заявленного, типы не совпали или algo другой — верните пустую строку.', 'def key_fingerprint(pubkey_line, algo):
    pass
', 'Модули base64 (b64decode с validate=True) и hashlib; длину типа читайте int.from_bytes(blob[:4], ''big'').', '{"func": "key_fingerprint", "tests": [{"args": ["ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIJ80k8WIHNVmYeoZm+4cPX6dBU7CWNUX+B2brTFyAeUx ka", "sha256"], "expected": "SHA256:7n39CWy8IIQo4QbnsL35WNF0M2OxMkGsyrtxszbq6cA"}, {"args": ["ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIJ80k8WIHNVmYeoZm+4cPX6dBU7CWNUX+B2brTFyAeUx ka", "md5"], "expected": "MD5:39:d8:bf:6f:36:9b:e2:48:d9:28:c8:9d:67:69:4b:88"}, {"args": ["ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIAAJ5RTvZuuKGUlWypNxHEHSP8hj5+1cYtISk0hIBYzi kb", "sha256"], "expected": "SHA256:MfJTW8HCm0mjHHpVUEWa4S0t3dBR12RmZfItg4WYwm8"}, {"args": ["ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIAAJ5RTvZuuKGUlWypNxHEHSP8hj5+1cYtISk0hIBYzi kb", "md5"], "expected": "MD5:5b:a2:f8:1e:2d:a7:75:66:17:5b:8b:9e:a2:95:69:1c"}, {"args": ["ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIAIiDILfEOpeidhx4Lw3a1HHQj+N60cE74oBFKSaXYQj", "sha256"], "expected": "SHA256:bCVt2cNt52Vpd0RJBMA68yFwSckqpgH+i4tQba670qA"}, {"args": ["ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIAIiDILfEOpeidhx4Lw3a1HHQj+N60cE74oBFKSaXYQj", "md5"], "expected": "MD5:cc:6b:fd:13:7e:90:6b:85:32:08:2f:1a:02:e2:4b:33"}, {"args": ["ecdsa-sha2-nistp256 AAAAE2VjZHNhLXNoYTItbmlzdHAyNTYAAAAIbmlzdHAyNTYAAABBBEEzf0CTrGY3+36J91GPPYwXd8BfD3Df7IspbKFMExzP1gAF1yQePYh4/kP/sY+c/7Ys/NRf9z+lPCYoRCRov04= e1", "sha256"], "expected": "SHA256:DmQmWKuoBNH11F3TDPiU7iuCNQBhsVPEhhRcARM3HxU"}, {"args": ["ecdsa-sha2-nistp256 AAAAE2VjZHNhLXNoYTItbmlzdHAyNTYAAAAIbmlzdHAyNTYAAABBBEEzf0CTrGY3+36J91GPPYwXd8BfD3Df7IspbKFMExzP1gAF1yQePYh4/kP/sY+c/7Ys/NRf9z+lPCYoRCRov04= e1", "md5"], "expected": "MD5:54:e0:07:cf:c7:20:0d:07:d2:f9:ce:6d:fa:49:d5:9e"}, {"args": ["ssh-rsa AAAAC3NzaC1lZDI1NTE5AAAAIJ80k8WIHNVmYeoZm+4cPX6dBU7CWNUX+B2brTFyAeUx wrong-label", "sha256"], "expected": ""}, {"args": ["ssh-ed25519 not*base64! x", "sha256"], "expected": ""}, {"args": ["ssh-ed25519", "sha256"], "expected": ""}, {"args": ["ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIJ80k8WIHNVmYeoZm+4cPX6dBU7CWNUX+B2brTFyAeUx", "sha1"], "expected": ""}, {"args": ["ssh-ed25519 AAAAC3NzaC1lZA==", "sha256"], "expected": ""}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 1, 'la1-proxyjump', 7, 'func', 'Цепочка ProxyJump', 'Напишите функцию jump_chain(config, target, default_user): список хопов, через которые ssh дойдёт до target. config — словарь «псевдоним Host → словарь параметров», где возможные ключи hostname (строка), user (строка), port (int) и proxyjump (строка). target — то, что набрано в команде ssh; default_user — имя пользователя, если ни команда, ни config его не задают. Хоп описывается строкой «user@hostname:port». Разбор имени (и у target, и у перехода): необязательное «user@» в начале, необязательное «:port» в конце, остальное — псевдоним; если псевдонима нет в config, он сам служит именем хоста, а параметров нет. Значение берётся так: user — из имени, иначе из параметров, иначе default_user; hostname — из параметров, иначе сам псевдоним; port — из имени, иначе из параметров, иначе 22. Параметр proxyjump — список переходов через запятую (none — переходов нет); они проходятся по порядку, и у каждого перехода собственный proxyjump из config тоже применяется (сначала его цепочка, затем он сам). В результате сначала идут хопы переходов в порядке соединения, последним — сам target. Если цепочка когда-либо возвращается к псевдониму, который уже разворачивается выше по цепочке (петля), верните пустой список.', 'def jump_chain(config, target, default_user):
    pass
', 'Рекурсивная функция expand(spec, seen): разберите spec, для каждого перехода из proxyjump вызовите expand с seen | {alias}, затем добавьте свой хоп.', '{"func": "jump_chain", "tests": [{"args": [{"bastion": {"hostname": "203.0.113.10", "user": "jump", "port": 2200}, "inner": {"hostname": "10.0.0.5", "proxyjump": "bastion"}, "db": {"hostname": "10.0.1.9", "user": "dba", "proxyjump": "inner,audit@gw:2022"}, "app": {"hostname": "10.0.2.4", "proxyjump": "ops@bastion:2201"}, "direct": {"hostname": "192.0.2.50", "proxyjump": "none"}, "a": {"proxyjump": "b"}, "b": {"proxyjump": "c"}, "c": {"proxyjump": "a"}, "twice": {"hostname": "10.9.9.9", "proxyjump": "bastion,bastion"}}, "bastion", "me"], "expected": ["jump@203.0.113.10:2200"]}, {"args": [{"bastion": {"hostname": "203.0.113.10", "user": "jump", "port": 2200}, "inner": {"hostname": "10.0.0.5", "proxyjump": "bastion"}, "db": {"hostname": "10.0.1.9", "user": "dba", "proxyjump": "inner,audit@gw:2022"}, "app": {"hostname": "10.0.2.4", "proxyjump": "ops@bastion:2201"}, "direct": {"hostname": "192.0.2.50", "proxyjump": "none"}, "a": {"proxyjump": "b"}, "b": {"proxyjump": "c"}, "c": {"proxyjump": "a"}, "twice": {"hostname": "10.9.9.9", "proxyjump": "bastion,bastion"}}, "inner", "me"], "expected": ["jump@203.0.113.10:2200", "me@10.0.0.5:22"]}, {"args": [{"bastion": {"hostname": "203.0.113.10", "user": "jump", "port": 2200}, "inner": {"hostname": "10.0.0.5", "proxyjump": "bastion"}, "db": {"hostname": "10.0.1.9", "user": "dba", "proxyjump": "inner,audit@gw:2022"}, "app": {"hostname": "10.0.2.4", "proxyjump": "ops@bastion:2201"}, "direct": {"hostname": "192.0.2.50", "proxyjump": "none"}, "a": {"proxyjump": "b"}, "b": {"proxyjump": "c"}, "c": {"proxyjump": "a"}, "twice": {"hostname": "10.9.9.9", "proxyjump": "bastion,bastion"}}, "db", "me"], "expected": ["jump@203.0.113.10:2200", "me@10.0.0.5:22", "audit@gw:2022", "dba@10.0.1.9:22"]}, {"args": [{"bastion": {"hostname": "203.0.113.10", "user": "jump", "port": 2200}, "inner": {"hostname": "10.0.0.5", "proxyjump": "bastion"}, "db": {"hostname": "10.0.1.9", "user": "dba", "proxyjump": "inner,audit@gw:2022"}, "app": {"hostname": "10.0.2.4", "proxyjump": "ops@bastion:2201"}, "direct": {"hostname": "192.0.2.50", "proxyjump": "none"}, "a": {"proxyjump": "b"}, "b": {"proxyjump": "c"}, "c": {"proxyjump": "a"}, "twice": {"hostname": "10.9.9.9", "proxyjump": "bastion,bastion"}}, "app", "me"], "expected": ["ops@203.0.113.10:2201", "me@10.0.2.4:22"]}, {"args": [{"bastion": {"hostname": "203.0.113.10", "user": "jump", "port": 2200}, "inner": {"hostname": "10.0.0.5", "proxyjump": "bastion"}, "db": {"hostname": "10.0.1.9", "user": "dba", "proxyjump": "inner,audit@gw:2022"}, "app": {"hostname": "10.0.2.4", "proxyjump": "ops@bastion:2201"}, "direct": {"hostname": "192.0.2.50", "proxyjump": "none"}, "a": {"proxyjump": "b"}, "b": {"proxyjump": "c"}, "c": {"proxyjump": "a"}, "twice": {"hostname": "10.9.9.9", "proxyjump": "bastion,bastion"}}, "direct", "root"], "expected": ["root@192.0.2.50:22"]}, {"args": [{"bastion": {"hostname": "203.0.113.10", "user": "jump", "port": 2200}, "inner": {"hostname": "10.0.0.5", "proxyjump": "bastion"}, "db": {"hostname": "10.0.1.9", "user": "dba", "proxyjump": "inner,audit@gw:2022"}, "app": {"hostname": "10.0.2.4", "proxyjump": "ops@bastion:2201"}, "direct": {"hostname": "192.0.2.50", "proxyjump": "none"}, "a": {"proxyjump": "b"}, "b": {"proxyjump": "c"}, "c": {"proxyjump": "a"}, "twice": {"hostname": "10.9.9.9", "proxyjump": "bastion,bastion"}}, "x.example.org", "me"], "expected": ["me@x.example.org:22"]}, {"args": [{"bastion": {"hostname": "203.0.113.10", "user": "jump", "port": 2200}, "inner": {"hostname": "10.0.0.5", "proxyjump": "bastion"}, "db": {"hostname": "10.0.1.9", "user": "dba", "proxyjump": "inner,audit@gw:2022"}, "app": {"hostname": "10.0.2.4", "proxyjump": "ops@bastion:2201"}, "direct": {"hostname": "192.0.2.50", "proxyjump": "none"}, "a": {"proxyjump": "b"}, "b": {"proxyjump": "c"}, "c": {"proxyjump": "a"}, "twice": {"hostname": "10.9.9.9", "proxyjump": "bastion,bastion"}}, "ann@x.example.org:2022", "me"], "expected": ["ann@x.example.org:2022"]}, {"args": [{"bastion": {"hostname": "203.0.113.10", "user": "jump", "port": 2200}, "inner": {"hostname": "10.0.0.5", "proxyjump": "bastion"}, "db": {"hostname": "10.0.1.9", "user": "dba", "proxyjump": "inner,audit@gw:2022"}, "app": {"hostname": "10.0.2.4", "proxyjump": "ops@bastion:2201"}, "direct": {"hostname": "192.0.2.50", "proxyjump": "none"}, "a": {"proxyjump": "b"}, "b": {"proxyjump": "c"}, "c": {"proxyjump": "a"}, "twice": {"hostname": "10.9.9.9", "proxyjump": "bastion,bastion"}}, "a", "me"], "expected": []}, {"args": [{"bastion": {"hostname": "203.0.113.10", "user": "jump", "port": 2200}, "inner": {"hostname": "10.0.0.5", "proxyjump": "bastion"}, "db": {"hostname": "10.0.1.9", "user": "dba", "proxyjump": "inner,audit@gw:2022"}, "app": {"hostname": "10.0.2.4", "proxyjump": "ops@bastion:2201"}, "direct": {"hostname": "192.0.2.50", "proxyjump": "none"}, "a": {"proxyjump": "b"}, "b": {"proxyjump": "c"}, "c": {"proxyjump": "a"}, "twice": {"hostname": "10.9.9.9", "proxyjump": "bastion,bastion"}}, "twice", "me"], "expected": ["jump@203.0.113.10:2200", "jump@203.0.113.10:2200", "me@10.9.9.9:22"]}, {"args": [{}, "h", "u"], "expected": ["u@h:22"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 1, 'la1-tmux-detached', 8, 'func', 'Отцепленные сеансы tmux', 'Напишите функцию detached_sessions(ls_output): разберите вывод «tmux ls» и верните список кортежей (имя, число_окон) для сеансов, к которым сейчас никто не подключён, — от самого нового к самому старому по времени создания; при равенстве — по имени по возрастанию. Строка вывода выглядит так: «имя: N windows (created Tue Nov  3 11:37:04 2026)», после чего могут идти « (group имя_группы)» и « (attached)» — именно в таком порядке, каждая часть необязательна. В имени могут быть пробелы, но нет двоеточия. Слово «windows» пишется так и при одном окне. Дата — день недели, месяц (Jan…Dec, три буквы), число (перед однозначным может быть лишний пробел), время ЧЧ:ММ:СС и год. Сеанс подключён, если в строке есть « (attached)». Строки, не похожие на описание сеанса (например «no server running on /tmp/tmux-1000/default»), пропускаются.', 'def detached_sessions(ls_output):
    pass
', 'Одно регулярное выражение с необязательными группами; дату превратите в кортеж (год, номер месяца, число, час, минута, секунда) и отсортируйте в два прохода: сначала по имени, затем по времени по убыванию (сортировка устойчива).', '{"func": "detached_sessions", "tests": [{"args": ["a_b: 1 windows (created Tue Nov  3 11:37:04 2026)\nbuild: 3 windows (created Mon Nov  2 09:01:00 2026) (attached)\nupgrade: 2 windows (created Tue Nov  3 10:15:02 2026)\nlogs: 1 windows (created Tue Nov  3 10:15:02 2026) (group main)\nmain: 4 windows (created Sun Nov  1 23:59:59 2026) (group main) (attached)\nold backup: 1 windows (created Fri Oct 30 08:00:00 2026)\n"], "expected": [{"__tuple__": ["a_b", 1]}, {"__tuple__": ["logs", 1]}, {"__tuple__": ["upgrade", 2]}, {"__tuple__": ["old backup", 1]}]}, {"args": [""], "expected": []}, {"args": ["no server running on /tmp/tmux-1000/default\n"], "expected": []}, {"args": ["error connecting to /tmp/tmux-1000/default (No such file or directory)\n"], "expected": []}, {"args": ["x: 1 windows (created Mon Jan  5 01:02:03 2026)\ny: 2 windows (created Sun Dec 28 23:00:00 2025)\n"], "expected": [{"__tuple__": ["x", 1]}, {"__tuple__": ["y", 2]}]}, {"args": ["b: 1 windows (created Tue Nov  3 10:00:00 2026)\na: 5 windows (created Tue Nov  3 10:00:00 2026)\nc: 2 windows (created Tue Nov  3 10:00:00 2026) (attached)\n"], "expected": [{"__tuple__": ["a", 5]}, {"__tuple__": ["b", 1]}]}, {"args": ["w: 2 windows (created Tue Nov 10 10:00:00 2026)\nv: 7 windows (created Tue Nov  3 10:00:00 2026)\n"], "expected": [{"__tuple__": ["w", 2]}, {"__tuple__": ["v", 7]}]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 1, 'la1-login-possible', 9, 'func', 'Пустит ли sshd', 'Напишите функцию login_possible(settings, user, method, forced): может ли пользователь user войти способом method ("key" или "password"). settings — словарь эффективных параметров sshd (имена в нижнем регистре, значения — строки; отсутствующий параметр означает значение по умолчанию). forced — bool: есть ли у ключа пользователя опция command. Проверки по порядку. 1) denyusers: список шаблонов через пробел (* и ? — подстановочные знаки); если user совпал хотя бы с одним — False. 2) allowusers: если список непуст и user не совпал ни с одним шаблоном — False. 3) Для user == "root" действует permitrootlogin (по умолчанию prohibit-password): no — False; prohibit-password и его синоним without-password — False для password; forced-commands-only — False для password, а для key — False, если forced равно False; yes ничего не запрещает. 4) Для method "key" нужно, чтобы pubkeyauthentication (по умолчанию yes) был yes; для "password" нужно, чтобы passwordauthentication (по умолчанию yes) был yes; значения сравниваются без учёта регистра. Другой method — False.', 'def login_possible(settings, user, method, forced):
    pass
', 'Сначала два списка пользователей, потом ветка root, потом включён ли сам способ.', '{"func": "login_possible", "tests": [{"args": [{}, "ann", "key", false], "expected": true}, {"args": [{}, "ann", "password", false], "expected": true}, {"args": [{}, "root", "key", false], "expected": true}, {"args": [{}, "root", "password", false], "expected": false}, {"args": [{"permitrootlogin": "yes"}, "root", "password", false], "expected": true}, {"args": [{"permitrootlogin": "no"}, "root", "key", true], "expected": false}, {"args": [{"permitrootlogin": "forced-commands-only"}, "root", "key", false], "expected": false}, {"args": [{"permitrootlogin": "forced-commands-only"}, "root", "key", true], "expected": true}, {"args": [{"permitrootlogin": "forced-commands-only", "passwordauthentication": "yes"}, "root", "password", true], "expected": false}, {"args": [{"passwordauthentication": "no"}, "ann", "password", false], "expected": false}, {"args": [{"passwordauthentication": "NO"}, "ann", "key", false], "expected": true}, {"args": [{"pubkeyauthentication": "no"}, "ann", "key", false], "expected": false}, {"args": [{"pubkeyauthentication": "no"}, "ann", "password", false], "expected": true}, {"args": [{"allowusers": "deploy admin ops*"}, "ops-bob", "key", false], "expected": true}, {"args": [{"allowusers": "deploy admin ops*"}, "carol", "key", false], "expected": false}, {"args": [{"allowusers": "deploy admin ops*", "denyusers": "ops-x*"}, "ops-xavier", "key", false], "expected": false}, {"args": [{"denyusers": "test? guest"}, "test1", "password", false], "expected": false}, {"args": [{"denyusers": "test? guest"}, "test12", "password", false], "expected": true}, {"args": [{"allowusers": "root"}, "root", "key", false], "expected": true}, {"args": [{}, "ann", "kerberos", false], "expected": false}]}');
